import { Accordion, Separator, Text } from "@chakra-ui/react";
import { useInspectorStore } from "../../store";
import { orderedBlockEventVerbs } from "../../try-assistant/ConversationLog/Event/orderedBlockEventLabel";
import { ConversationEventType, type ConversationEvent } from "../../types";
import { CommonEventInfo, DetailView, EventAccordionItem, InfoField } from "./blocks";

export type OrderedBlockLifecycleEvent = ConversationEvent & {
  skillId: string;
  blockId: string;
};

interface OrderedBlockEventInfoProps {
  event: OrderedBlockLifecycleEvent;
  onClose: () => void;
}

export const OrderedBlockEventInfo = ({ event, onClose }: OrderedBlockEventInfoProps) => {
  const skillCatalog = useInspectorStore((s) => s.skillCatalog);
  const verb = orderedBlockEventVerbs[event.conversationEventType] ?? "entered";
  const catalogSkill = skillCatalog?.[event.skillId];
  const showStepId =
    event.conversationEventType !== ConversationEventType.OrderedBlockEntered &&
    Boolean(event.stepId);

  return (
    <DetailView title={`Block ${verb}`} onClose={onClose}>
      <InfoField label="Skill ID">
        <Text textStyle="sm">{event.skillId}</Text>
      </InfoField>

      {catalogSkill && (
        <InfoField label="Name">
          <Text textStyle="sm">{catalogSkill.name ?? catalogSkill.id}</Text>
        </InfoField>
      )}

      <InfoField label="Block ID">
        <Text textStyle="sm">{event.blockId}</Text>
      </InfoField>

      {showStepId && (
        <InfoField label="Step ID">
          <Text textStyle="sm">{event.stepId}</Text>
        </InfoField>
      )}

      <Separator mt="2" />
      <Accordion.Root collapsible multiple>
        <EventAccordionItem title="Event details" value="event-details">
          <CommonEventInfo event={event} />
        </EventAccordionItem>
      </Accordion.Root>
    </DetailView>
  );
};
